from pathlib import Path
import json,hashlib
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-retained-selection-contracts-rev1'
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def ref(p):return dict(path=Path(p).as_posix(),sha256=hashlib.sha256(Path(p).read_bytes()).hexdigest())
def save(n,v):
 p=O/n
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
notes={
'CANONICAL_VISUAL_SELECTION_COMPONENT.md':'Existing532 audit owns sole fresh1143 occurrence;534 view references it with matching one-use capability. Empty/ineligible completed selection still allocates audit, no synthetic experience for no detections. Capacity0/1/2,three units,one binding/claim are exact533 adapter bounds, not permission to widen schema. Domain checks precede allocation; failed projection closes capability, enclosing scheduler owns allocator rollback. New transformation version distinct from frozen public predecessor; structural decoding not producer admission or memory authority.',
'EMPTY_VISUAL_SELECTION_COMPONENT.md':'Actual completed no-detection observation creates empty pool for normal one-use selector without fabricated SEM experience. Completed empty selection owes audit/source enrollment but no acquisition. No detections and positive source at zero capacity remain distinct producer branches despite same empty view. Pool allocates no occurrence/state and authenticates no source; public observation/audit binding remains an outer obligation.',
'CONTRASTIVE_ATTRIBUTION_COMPONENT.md':'Deliberately fallible four-trial hypothesis: exactly two(0,0)->(1,0) strokes/two stationary, identical before intervals, bounded0..100 rational levels/0..7 coordinates. Conservative changes after.lower-before.upper and after.upper-before.lower; support requires minimum stroke lower strictly above0 and maximum stationary upper. Endpoint equality/overlap/missing contrast yields Unavailable, not no causation. Malformed operands reject. No midpoint/tolerance/confidence/negative-effect/causal-effect estimate. Same permitted observations under genuinely caused or independently driven histories must yield same Supported: confounding is a scientific limit, not source bug. Preserve all four trials including stationary basis. Identity-free component cannot authenticate actual distinct recalled history, target connection or public write; no general causal/Need/surprise substitution.',
'FOCAL_POSITION_PAIR_ATTRIBUTION_COMPONENT.md':'Trusted index0..3 binds real recalled consequence group before evaluation; transient address not identity or trial-label authority. Actual unchanged position-pair consumer supplies reads. Supported only when consumed focal motion is stroke; focal stationary remains Unavailable despite supported global contrast. No reread/source schedule. Full consumed contrast can earn use while focal result earns no outcome significance; early failure credits only actual reads. Unfocused/older consumers retained; public focal/read/result/owner binding remains separate.',
'EVENT_ASSOCIATION_SETTLEMENT_COMPONENT.md':'Positive event acquisition supplies at mostthree strengths; null only independent retention request. Body/episode survivors/use/significance not graph operands. Formation decays using target minus committed LastUpdatedAt, exact round-even arithmetic, bounds and empty-node normalization; even empty result advances time. Retention-only neither decays nor advances LastUpdatedAt, including removal of every edge.30-node carrier and directed-edge/scale bounds are finite profile constraints;31st node rejects, not implicit lossy reduction. Multiple same-instant formations unqualified; detached candidate has no allocation/commit authority.',
'RETAINED_POSITION_PAIR_ATTRIBUTION_COMPONENT.md':'Two separately retained EventContinuant acquisitions with exact child/view addresses supply observed positions; no old position copied into fresh episode. Observation time<=acquisition<evaluation and strict start/end ordering; same acquisition rejects. Validate all supplied projections before evaluation without use credit. Actual start read first; null/nonorigin stops before end and intervals/later trials. Deduplicated actual child reads earn use only on one-shot finish; invalid unread position still rejects structurally without mutation. Focal target never expands to both positions. No general motion inference or public authority from trusted projection.',
'RETAINED_ATTRIBUTION_USE_COMPONENT.md':'Detached memory/read-set/trial adapter trusted, not caller-authenticated public evidence. All bindings/projections validated then frozen; validation earns no cognitive credit. Retained acquired-before-evaluation addresses must exist/admitted; detached operands earn no memory use. Evaluate motion,before,after in declared order, stopping on unavailability; distinct actually read children only, not all bound values. Unavailable is completed assessment, not transaction failure. Session-bound opaque result can finish once; returns candidate result/protection, scheduler commits both or neither. Close disables tokens; no persistent occurrence or display-feedback. Same-instant retention/new formation outside first scope.',
'RETAINED_CONTEXT_GROUPING_COMPONENT.md':'Use already bound PerceivedTrialContextEvidence companions, not reconstructed full SEM or source-archive lookup. Same event-file exactBefore/twoMotion/After observed-time order; missing/excess unavailable, duplicate experience/inconsistent chronology reject.16 companions/one selected candidate per occurrence is bounded apparatus, not multi-child deduplication. Structural copying not winning recollection authentication; grouping reads no memory root and grants no use/significance. Full-experience component remains differential control; representation dependency removed without retiring evidence distinctions.',
'RETAINED_POSITION_TRIAL_GROUPING_COMPONENT.md':'At most16 unique safe same-observer experiences with admitted roles. ExactBefore/twoMotion/After; Before<=start<end<After and explicit observation time rather than ID/input order. Duplicate times reject; excessAmbiguousRole/missingIncompleteContext/absentMissingContext distinct. No subset search repairs ambiguity. Return existing identities/context only, no new motion/trial identity, samples, target or causal verdict. Displayed neutralMotion labels are authored apparatus, not general segmentation. Prior one-motion grouping retained.',
'INDEPENDENT_ASSOCIATION_ACCESS_COMPONENT.md':'Local activation union supplies exact graph-zero for retained episode keys absent from graph then calls unchanged EAM. Zero is no graph contribution, not absent/negative evidence, importance or learned node. Retain all distinct episode keys in averaging denominator, not intersection only. Graph-only keys cannot create episodes; empty graph still permits base recall and empty episode set has no target. Existing unknown-key rejection remains when composition omitted.32-key union bound is workload, no persistent graph insertion/payload lookup/learning/reinforcement; survivor/cue provenance external.'
}
notes={'docs/formal/'+k:v for k,v in notes.items()}
ip=P/'campaign3-history-source-roles-rev186/index.json';ix=load(ip);entries={x['path']:x for x in load(B/'manifest.json')['entries']}
chain=[ref(P/'GENERAL_ATTENTION_QUALIFICATION_2026_09_20.md'),ref(P/'campaign3-history-source-component-contracts-rev1/review.json')]
