save('review.json',dict(status='NINE NEW RETAINED/SELECTION CONTRACTS; ONE PRIOR REVIEW REBOUND',checker=ref(__file__),sourceIndex=ref(ip),sourceRoles=sources,rows=rows,priorAssociationReview=prior,preservedArtifacts=[],limits=['Exact original Markdown paragraphs retained; arithmetic/code examples are normative candidate semantics, not new runtime results.','Later GA public qualification does not prove every proposed component vector independently executed or select general causal/attention/retention laws. GA16 consumed experiences/one endpoint and equal final protection states remain bounded.','Trusted adapters, read domains, source enrollment, PRJ and atomic owner commit remain distinct from structural codec checks.','No new runtime/test/build/model/allocation/verdict or obligation closure. Existing source provenance gaps and independent adequacy remain open.'],obligations=['RO-C3-014','RO-C3-019','RO-C3-020','RO-C3-021']))
save('check.json',dict(status='PASS SCOPED RETAINED/SELECTION CONTRACT RECONCILIATION',sources=9,originalNarrativeOccurrences=len(rows),originalBackingOccurrences=0,review=ref(O/'review.json')))
assert all(p.stat().st_size<50000000 for p in O.iterdir())
print(json.dumps(load(O/'check.json')))
